'use strict';
const sb=supabase.createClient('https://radskybbymadavveatzn.supabase.co','sb_publishable_VJh0qSiBA0OIcG7YqnLyjA_-YwiTlMT',{auth:{storageKey:'mylist-auth-v1',persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data={families:[],accounts:[],invitations:[],profiles:[]},tab='families',session=null,removal=null,loading=false,mutating=false;
const systemTheme=matchMedia('(prefers-color-scheme:dark)');function changeTheme(v){localStorage.setItem('mylist-theme',v);applyTheme()}function applyTheme(){const v=localStorage.getItem('mylist-theme')||'system';$('theme').value=v;const dark=v==='dark'||v==='system'&&systemTheme.matches;document.documentElement.dataset.theme=dark?'dark':'light';document.querySelector('meta[name="theme-color"]').content=dark?'#121b17':'#f6f7f2'}systemTheme.addEventListener('change',applyTheme);window.addEventListener('storage',applyTheme);applyTheme();
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('toast').hidden=true,5000)}
const profile=id=>data.profiles.find(p=>p.user_id===id),family=id=>data.families.find(f=>f.id===id),date=s=>s?new Date(s).toLocaleDateString('ro-RO'):'—';
function alias(a){return profile(a?.user_id)?.alias||a?.email||'Administrator invitat'}
function adminAccount(f){return data.accounts.find(a=>a.user_id===f.admin_id)||data.accounts.find(a=>a.email===f.owner_email)}
function matches(...values){const q=$('search').value.trim().toLocaleLowerCase('ro');return values.some(v=>String(v||'').toLocaleLowerCase('ro').includes(q))}
function render(){const pending=data.invitations.filter(i=>i.status==='pending').length,active=data.accounts.filter(a=>a.accepted_at).length;const values=[['Familii',data.families.filter(f=>data.accounts.some(a=>a.family_id===f.id)).length],['Conturi active',active],['Invitații în așteptare',pending],['Invitații trimise',data.invitations.filter(i=>i.send_count>0).length]];$('metrics').innerHTML=values.map(([label,n])=>`<div class="metric"><strong>${n}</strong><span>${label}</span></div>`).join('');$('tab-invitations').textContent=`Invitații${pending?' · '+pending:''}`;renderRows()}
function selectTab(value){tab=value;$('search').value='';renderRows()}
function renderRows(){document.querySelectorAll('[role=tab]').forEach(b=>b.setAttribute('aria-selected',b.id==='tab-'+tab));let rows=[];
 if(tab==='families')rows=data.families.filter(f=>data.accounts.some(a=>a.family_id===f.id)).filter(f=>matches(f.owner_email,alias(adminAccount(f)))).map(f=>{const occupied=data.accounts.filter(a=>a.family_id===f.id),active=occupied.filter(a=>a.accepted_at).length,waiting=occupied.length-active,sent=data.invitations.filter(i=>i.family_id===f.id&&i.invited_by===f.admin_id&&i.send_count>0).length;return `<article class="row"><div class="avatar" aria-hidden="true">${esc(alias(adminAccount(f)).charAt(0).toLocaleUpperCase('ro'))}</div><div class="row-info"><strong>${esc(alias(adminAccount(f)))}</strong><small>${esc(f.owner_email)}</small><small>Administrator de familie${f.admin_id?'':' · Invitație în așteptare'}</small><small>${sent} invitații de familie trimise · ${active} membri activi · ${waiting} în așteptare</small></div><div class="quota"><b>${occupied.length} din 4 locuri</b><progress max="4" value="${occupied.length}" aria-label="Locuri ocupate"></progress><small>${Math.max(0,4-occupied.length)} invitații disponibile</small></div></article>`});
 if(tab==='invitations')rows=data.invitations.filter(i=>matches(i.email,family(i.family_id)?.owner_email,alias(data.accounts.find(a=>a.user_id===i.invited_by)))).map(i=>`<article class="row"><div class="row-info"><strong>${esc(i.email)}</strong><small>${i.kind==='administrator'?'Administrator de familie':'Membru al familiei'} · ${esc(family(i.family_id)?.owner_email||'')}</small><small>Invitat de ${esc(alias(data.accounts.find(a=>a.user_id===i.invited_by)))} · ${date(i.sent_at||i.created_at)}${i.send_count>1?' · '+i.send_count+' trimiteri':''}</small></div><span class="pill">${({pending:'În așteptare',accepted:'Acceptată',cancelled:'Acces retras',failed:'E-mail netrimis'})[i.status]}</span>${i.status==='pending'?`<div class="row-actions"><button data-id="${i.id}" onclick="resend(this.dataset.id,this)">Retrimite</button><button data-id="${i.id}" onclick="cancelInvitation(this.dataset.id,this)" class="danger">Retrage</button></div>`:''}</article>`);
 if(tab==='accounts')rows=data.accounts.filter(a=>a.accepted_at&&matches(a.email,alias(a),family(a.family_id)?.owner_email)).map(a=>{const f=family(a.family_id),protectedAccount=a.is_admin||f?.admin_id===a.user_id;return `<article class="row"><div class="avatar">${esc(alias(a).charAt(0).toLocaleUpperCase('ro'))}</div><div class="row-info"><strong>${esc(alias(a))}</strong><small>${esc(a.email)}</small><small>${a.is_admin?'Administrator MyList':f?.admin_id===a.user_id?'Administrator de familie':'Membru'} · Familia ${esc(f?.owner_email||'')}</small></div>${protectedAccount?'<span class="pill">Protejat</span>':`<button class="danger" data-id="${a.user_id}" onclick="confirmRemoval(this.dataset.id)">Șterge</button>`}</article>`});
 $('rows').innerHTML=rows.join('')||'<div class="empty">Niciun rezultat.</div>';
}
async function refresh(){if(!session||loading||mutating)return;loading=true;const uid=session.user.id;try{const r=await sb.rpc('mylist_admin_overview');if(session?.user.id!==uid)return;if(r.error)throw r.error;data=r.data;$('login').hidden=true;$('dashboard').hidden=false;render()}catch(e){data={families:[],accounts:[],invitations:[],profiles:[]};$('dashboard').hidden=true;$('rows').innerHTML='';$('login').hidden=false;$('loginStatus').textContent=e.message||'Acces indisponibil'}finally{loading=false}}
async function signIn(e){e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const r=await sb.auth.signInWithPassword({email:$('email').value.trim(),password:$('password').value});if(r.error)throw r.error;$('password').value='';session=r.data.session;await refresh()}catch{$('loginStatus').textContent='Conectarea nu a reușit. Verifică e-mailul și parola.'}finally{b.disabled=false}}
async function signOut(){await sb.auth.signOut({scope:'local'});session=null;data={families:[],accounts:[],invitations:[],profiles:[]};$('dashboard').hidden=true;$('rows').innerHTML='';$('login').hidden=false;$('loginStatus').textContent=''}
async function sendInvitation(email,kind){const r=await sb.functions.invoke('mylist-invite',{body:{email,kind}});if(r.error){let message='Invitația nu a fost trimisă';try{message=(await r.error.context.json()).error||message}catch{}throw Error(message)}}
async function mutate(button,task,message){if(mutating)return;mutating=true;button.disabled=true;try{await task();toast(message)}catch(e){toast(e.message||'Operația nu a reușit')}finally{mutating=false;button.disabled=false;await refresh()}}
async function inviteAdministrator(e){e.preventDefault();await mutate($('sendInvite'),async()=>{await sendInvitation($('inviteEmail').value.trim(),'administrator');$('inviteEmail').value=''},'Invitație trimisă pe e-mail')}
async function resend(id,button){const i=data.invitations.find(i=>i.id===id);if(i)await mutate(button,()=>sendInvitation(i.email,i.kind),'Invitație retrimisă pe e-mail')}
async function cancelInvitation(id,button){const i=data.invitations.find(i=>i.id===id);if(!i)return;await mutate(button,async()=>{const r=await sb.rpc('mylist_action',{op:'cancel_invite',p:{email:i.email}});if(r.error)throw r.error},'Invitație retrasă')}
function confirmRemoval(id){const a=data.accounts.find(a=>a.user_id===id);if(!a||a.is_admin||family(a.family_id)?.admin_id===id)return;removal=a;$('confirmEmail').textContent=a.email;$('confirmCheck').checked=false;$('confirm').showModal()}
async function removeAccount(e){e.preventDefault();if(!$('confirmCheck').checked||!removal)return;await mutate(e.target.querySelector('.danger'),async()=>{const r=await sb.rpc('mylist_action',{op:'remove_account',p:{email:removal.email}});if(r.error)throw r.error;$('confirm').close()},'Acces retras din MyList')}
sb.auth.onAuthStateChange((event,next)=>{session=next;if(!next){$('dashboard').hidden=true;$('login').hidden=false;data={families:[],accounts:[],invitations:[],profiles:[]}}else setTimeout(refresh,0)});sb.auth.getSession().then(r=>{session=r.data.session;refresh()});setInterval(()=>{if(document.visibilityState==='visible'&&!document.querySelector('dialog[open]'))refresh()},15000);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refresh()});
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
